def min_nop_instructions(program):
    memory_address = 0
    nop_count = 0

    for char in program:
        if memory_address % 4 != 0:
            nop_count += 1
            memory_address += 4 - (memory_address % 4)
        memory_address += 1

    return nop_count

if __name__ == "__main__":
    import sys
    input = sys.stdin.read().strip()
    print(min_nop_instructions(input))
